import {discoverCardano,connectCardano,requestBuilder,finishBuilder} from './cardano-wallet.mjs';
export function installCardanoUI({document,root,getClient,onAuthorized}){
 const $=id=>document.getElementById(id);let session=null,pending=null,busy=false,version=0;
 const zh=()=>document.documentElement.lang.startsWith('zh');const text=(en,cn)=>zh()?cn:en;
 const status=(en,cn)=>{$('cardanoStatus').textContent=text(en,cn)};
 function invalidate(){version++;pending=null;$('builderReview').hidden=true;$('builderConsent').checked=false;}
 function reset(){invalidate();session=null;$('cardanoAddress').textContent='';$('requestBuilder').disabled=true;status('Choose an installed wallet. Connecting only reads its address and network.','选择已安装钱包。连接步骤仅读取地址和网络。');}
 function discover(){const holder=$('cardanoChoices');holder.replaceChildren();for(const row of discoverCardano(root.cardano??{})){const b=document.createElement('button');b.type='button';b.className='ghost';b.disabled=!row.installed||busy;b.textContent=row.name+' · '+text(row.installed?'Connect':'Not installed',row.installed?'连接':'未安装');b.onclick=async()=>{if(busy)return;reset();const v=version,network=getClient().network;busy=true;discover();status('Approve the connection in your wallet. No transaction is requested.','请在钱包中批准连接；此步骤不请求交易。');try{const next=await connectCardano(root.cardano??{},row.id,network);if(v!==version||getClient().network!==network)return;session=next;$('cardanoAddress').textContent=next.name+' · '+next.address;$('requestBuilder').disabled=false;status('Wallet connected. Strike account is not authorized yet. Enter a valid Builder Code to continue, or use your existing API Wallet below.','钱包已连接，Strike 账户尚未授权。输入有效 Builder Code 继续，或使用下方已有 API Wallet。')}catch(e){if(v===version)$('cardanoStatus').textContent=e.message}finally{busy=false;discover()}};holder.append(b)}}
 $('refreshWallets').onclick=discover;$('builderCode').addEventListener('input',invalidate);
 $('requestBuilder').onclick=async()=>{if(!session||busy)return;invalidate();const v=version,client=getClient();busy=true;$('requestBuilder').disabled=true;try{status('Requesting the official Strike authorization message…','正在请求 Strike 官方授权消息…');const next=await requestBuilder(session,$('builderCode').value);if(v!==version||getClient()!==client)return;pending=next;$('builderMessage').textContent=next.message;$('builderReview').hidden=false;status('Review the exact official message, then approve signing in your wallet.','请查看官方消息全文，再在钱包中批准签名。')}catch(e){if(v===version)$('cardanoStatus').textContent=e.message}finally{busy=false;$('requestBuilder').disabled=!session}};
 $('signBuilder').onclick=async()=>{if(!pending||busy)return;if(!$('builderConsent').checked){status('Acknowledge the authorization effects before signing.','请先确认已了解授权的影响。');return}const p=pending,v=version,client=getClient();busy=true;$('signBuilder').disabled=true;try{status('Waiting for wallet signature and Strike verification…','等待钱包签名与 Strike 核验…');const result=await finishBuilder(p);if(v!==version||getClient()!==client)return;client.disconnect();client.wallet=result.wallet;await client.syncClock();invalidate();await onAuthorized();status('Strike authorization verified. Account reads are now enabled. No trade was sent.','Strike 授权已核验，可读取账户；未发送交易。')}catch(e){if(v===version){invalidate();$('cardanoStatus').textContent=e.message+' · '+text('Request a fresh challenge before retrying.','重试前请重新请求授权消息。')}}finally{busy=false;$('signBuilder').disabled=false}};
 $('network').addEventListener('change',reset);$('disconnect').addEventListener('click',reset);$('keyForm').addEventListener('submit',reset);$('useLocal').addEventListener('click',reset);$('language').addEventListener('change',()=>{discover();if(!session)reset()});$('connectToggle').addEventListener('click',discover);reset();discover();
 return {reset};
}
